mapper.select:
SELECT DISTINCT dataTable.device_code as deviceCode, ch.facade, dataTable.device_name, ch.channel_code, ch.channel_name, ch.channel_status as status, dataTable.province_code as provinceId,pro.area_name as provinceName,dataTable.city_code as cityId, city.area_name as cityName,dataTable.county_code as countyId,county.area_name as countyName, dataTable.town_code as townCode, town.area_name as townName, dataTable.longitude,dataTable.latitude, 'false' AS checked, '1' AS proLevel, '2' AS cityLevel,'3' AS countryLevel,'4' AS devLevel,'5' AS chanLevel, case when IFNULL(dc.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
case when IFNULL(artc.id,0) = 0 then '0' else '1' end tagCollect,
(case when length(IFNULL(dr.device_name, '')) = 0 then dataTable.device_name else dr.device_name end ) deviceAlias, (case when length(IFNULL(dr.channel_name, '')) = 0 then ch.channel_name else dr.channel_name end ) channelAlias, dataTable.category_code as categoryCode,dataTable.site_code,dataTable.device_status,dataTable.image_url FROM (SELECT DISTINCT m.device_code, ord.tenant_id, m.site_code,m.device_status,ord.industry_code, m.device_name, m.province_id as province_code, m.city_id as city_code, m.town_code, m.county_id as county_code, ord.delete_flag, m.longitude, m.latitude,m.category_code,ord.accept_node,m.image_url FROM vm_order_devices ord LEFT JOIN vm_device_info_t m on m.device_code = ord.device_code and m.delete_flag= '0' where ord.ord_status in (0, 1, 2) and ord.delete_flag= '0'
and ord.industry_code = #{param.industryCode}
and ord.tenant_id = #{param.tenantId}
and m.category_code in
#{item}
AND ord.device_code IN
#{item}
) dataTable LEFT JOIN vm_channel_info_t ch on ch.device_code = dataTable.device_code LEFT JOIN sys_area pro on pro.area_code = dataTable.province_code LEFT JOIN sys_area city on city.area_code = dataTable.city_code LEFT JOIN sys_area county on county.area_code = dataTable.county_code LEFT JOIN vm_tenant_device_channel_rel_t dr on dr.device_code = dataTable.device_code and dr.delete_flag = '0' AND dr.tenant_id = dataTable.tenant_id and dr.industry_code = dataTable.industry_code AND dr.channel_code = ch.channel_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = dataTable.device_code AND dct.coll_obj_type = '5' AND dct.user_id = #{param.userId} LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = ch.channel_code AND dc.coll_obj_type = '6' AND dc.user_id = #{param.userId} LEFT JOIN sys_area town on town.area_code = dataTable.town_code
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = dataTable.device_code and art.coll_obj_type = '5' and art.user_id = #{param.userId} LEFT JOIN vm_ar_tags_tree_user_rel artc on artc.coll_obj_code = ch.channel_code and artc.coll_obj_type = '6' and artc.user_id = #{param.userId}
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = dataTable.device_code and ch.channel_code = vcdit.channel_code and vcdit.delete_flag = '0' and dataTable.tenant_id = vcdit.tenant_id AND dataTable.industry_code = vcdit.industry_code
join vm_water_level_info_t water on water.device_code = dataTable.device_code and water.delete_flag = '0' and dataTable.tenant_id = water.tenant_id AND dataTable.industry_code = water.industry_code
WHERE ch.delete_flag = '0'
and dc.user_device_coll_id IS NOT NULL
and artc.coll_obj_code IS NOT NULL
${param.dataScope}
and dataTable.tenant_id in
#{item}
and ch.channel_status in
#{item}
ORDER BY dataTable.province_code, dataTable.city_code, dataTable.county_code, dataTable.town_code, dataTable.device_code, ch.channel_code

SELECT t1.dept_id AS code,t1.dept_name AS name,t1.dept_level AS level, t1.parent_id AS parentCode,'false' AS checked, 0 AS num, 0 AS onlineNum FROM sys_dept t1 WHERE t1.del_flag = '0'
AND t1.dept_id in
#{item}
and t1.tenant_id = #{tenantId}

SELECT DISTINCT deviceCode, devName, height, streetCode, streetName, status, deviceStatusName, orderStatusName, orderStatus, longitude, latitude, location, tenantId, industry_code, provinceName, provinceCode, cityName, cityCode, countryName, countryCode, modelId, categoryCode, modelName, collectType, collectMethod, siteCode, deviceModelCode, visualRadius FROM ( SELECT DISTINCT od.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) devName,
( case when length(IFNULL(ten.channel_name, '')) = 0 then ci.channel_name else ten.channel_name end ) chanName,
m.town_code as streetCode, town.area_name as streetName, m.device_status as status, (CASE WHEN m.device_status = '0' THEN '在线' WHEN m.device_status = '1' THEN '离线' WHEN m.device_status = '2' THEN '从未连接' END) deviceStatusName, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName, od.ord_status as orderStatus, m.longitude, m.latitude, m.location, m.height, m.collect_type collectType, m.collect_method collectMethod, m.device_model_code deviceModelCode, m.site_code siteCode, od.tenant_id as tenantId, od.industry_code, pro.area_name as provinceName, pro.area_code as provinceCode, city.area_name as cityName, city.area_code as cityCode, county.area_name as countryName, county.area_code as countryCode, m.model_code as modelId, m.category_code as categoryCode, m.visual_radius as visualRadius, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = '103' AND DICT_VALUE = m.model_code limit 1) modelName FROM vm_order_devices od LEFT JOIN vm_device_info_t m on m.device_code = od.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = od.device_code and ten.tenant_id =#{param.tenantId}od.tenant_id and ten.delete_flag='0' and ten.industry_code = #{param.industryCode}od.industry_code LEFT JOIN sys_area pro on pro.area_code = m.province_id LEFT JOIN sys_area city on city.area_code = m.city_id LEFT JOIN sys_area county on county.area_code = m.county_id LEFT JOIN sys_area town on town.area_code = m.town_code
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = m.device_code and vod.delete_flag = '0' and vod.tenant_id = od.tenant_id and vod.device_type = 4
LEFT JOIN vm_channel_info_t ci ON ci.device_code = od.device_code where od.delete_flag = '0' AND m.delete_flag = '0' AND ci.delete_flag = '0'
and vod.dept_id in
#{id}
and m.device_code in
#{id}
AND m.province_id = #{param.provinceCode}
AND m.city_id = #{param.cityCode}
AND m.county_id = #{param.countryCode}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_code = #{param.deviceCode}
and m.device_status = #{param.status}
and m.model_code = #{param.modelId}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
and ci.channel_code like CONCAT('%', #{param.channelCode}, '%')
${param.dataScope} ORDER BY field(od.ord_status,1,0,2,4,3) ASC
and m.device_code = #{param.deviceCode}
) dt
and dt.devName like CONCAT('%', #{param.devName}, '%')
and dt.chanName like CONCAT('%', #{param.channelName}, '%')
GROUP BY tenantId,industry_code,deviceCode ORDER BY provinceCode,cityCode,countryCode,streetCode,deviceCode

select t.device_code as deviceCode, GROUP_CONCAT(t.id) as id, GROUP_CONCAT(t.DEPT_ID) as orgId,
GROUP_CONCAT(org.DEPT_NAME separator '，') as orgName
from vm_organ_device_rel_t t LEFT JOIN sys_dept org ON org.DEPT_ID = t.DEPT_ID
where
t.delete_flag = '0'
and t.device_type = 4 and org.DEL_FLAG='0' and org.`STATUS` = '0'


        and t.device_code in

            #{item}



        and t.device_code = #{deviceCode}



    and t.tenant_id = #{tenantId}


    and t.dept_id = #{orgCode}


    and t.industry_code = #{industryCode}

group by t.device_code

select * from ( SELECT DISTINCT ch.device_code as parentDeviceCode, ( case when length(IFNULL(ten.channel_name, '')) = 0 then ch.channel_name else ten.channel_name end ) channelName, ch.channel_code as channelCode, ch.channel_status as status, ch.visual_range as visualRange, ch.horiz_range as horizRange, ch.verti_range as vertiRange, ten.tenant_id as tenantId FROM vm_channel_info_t ch LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = ch.device_code AND ten.channel_code = ch.channel_code AND ten.tenant_id = #{tenantId} where ch.delete_flag = '0'
and ch.device_code in
#{item}
and ch.channel_code like CONCAT('%', #{channelCode}, '%')
) dt
and dt.channelName like CONCAT('%', #{channelName}, '%')

SELECT/*+ set(enable_nestloop off)*/ distinct dev.device_code, (case when length(IFNULL(tdr.device_name, '')) = 0 then dev.device_name else tdr.device_name end) as device_name, dev.device_status as status, ifnull(dev.height, 0) as height, dev.location, dev.latitude, dev.longitude, dev.site_code, dev.model_code, dict.dict_label model_name, dev.category_code FROM vm_device_info_t dev left join vm_order_devices t1 on dev.device_code = t1.device_code left join sys_dict_data dict on dict_type = 103 and dict.dict_value = dev.model_code left join vm_tenant_device_channel_rel_t tdr on tdr.device_code = dev.device_code and tdr.tenant_id = t1.tenant_id AND tdr.industry_code = t1.industry_code
left join vm_organ_device_rel_t rel on rel.device_code=dev.device_code and rel.delete_flag='0' and rel.device_type = 4
LEFT JOIN vm_order_algorithms t2 ON t2.order_code = t1.order_code AND t2.package_code = t1.package_code
LEFT JOIN vm_device_labels_rel t3 ON dev.device_code = t3.device_code AND t1.tenant_id = t3.tenant_id
LEFT JOIN vm_organ_device_rel_t t4 ON t1.tenant_id = t4.tenant_id AND t1.industry_code = t4.industry_code AND dev.device_code = t4.device_code
,vm_channel_info_t chan where dev.device_code = chan.device_code AND chan.delete_flag = '0' and t1.delete_flag = '0' and dev.delete_flag = '0' and t1.ord_status in (0,1,2)
and rel.dept_id like CONCAT(#{param.orgId},'%')
and rel.dept_id IN
#{orgId}
and dict.dict_value = #{param.modelCode}
and dict.dict_value IN
#{modelCodeItem}
AND dev.category_code IN
#{item}
AND dev.model_code IN
#{item}
AND dev.device_status IN
#{item}
AND t2.algorithm_code IN
#{item}
AND t3.label_id IN
#{item}
AND t4.delete_flag = '0' AND t4.device_type = '4' AND t4.dept_id IN
#{item}
${param.dataScope} order by height desc,dev.device_status,dev.device_code

SELECT distinct dev.device_code, dev.device_status, ifnull(dev.height, 0) as height,
(CASE WHEN length(IFNULL(tdr.device_name, '')) = 0 then dev.device_name else tdr.device_name end) as device_name,
dev.location, dev.latitude, dev.longitude, dev.site_code, dev.model_code, dict.dict_label model_name,
ch.channel_code, ch.channel_status, ch.channel_name, ch.channel_status,

    IFNULL(ROUND(ST_DISTANCE(POINT(#{param.orderLong},#{param.orderLat}),POINT(dev.longitude,dev.latitude))*111195,0),100000000) as rangeMeter,

CASE WHEN IFNULL(dc.user_device_coll_id, 0) = 0 THEN '0' ELSE '1' END isMonitor,
CASE WHEN IFNULL(dc.user_device_coll_id, 0) = 0 THEN 0 ELSE 1 END isMonitorNum
FROM vm_device_info_t dev
LEFT JOIN vm_order_devices t1 ON dev.device_code = t1.device_code
LEFT JOIN sys_dict_data dict ON dict_type = '103' AND dict.dict_value = dev.model_code
LEFT JOIN vm_channel_info_t ch ON ch.device_code = dev.device_code
LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = ch.channel_code
AND dc.coll_obj_type = '6' AND dc.user_id = #{param.userId}
LEFT JOIN vm_tenant_device_channel_rel_t tdr ON tdr.device_code = dev.device_code
AND tdr.tenant_id = t1.tenant_id AND tdr.industry_code = t1.industry_code
WHERE t1.delete_flag = '0' AND dev.delete_flag = '0' AND ch.delete_flag = '0' AND t1.ord_status in (0,1,2)
AND dev.device_code != '' AND dev.device_code IS NOT NULL
AND ch.channel_code != '' AND ch.channel_code IS NOT NULL

    AND dev.device_code IN

        #{labelIdItem}



    AND  dev.device_status = #{param.deviceStatus}


    and dev.model_code  IN

        #{modelCodeItem}



    AND  dev.province_id = #{param.deviceArea}


    AND  dev.city_id = #{param.deviceArea}


    AND  dev.county_id = #{param.deviceArea}


    AND  dev.town_code = #{param.deviceArea}

${param.dataScope}


        ORDER BY IFNULL(ROUND(ST_DISTANCE(POINT(#{param.orderLong},#{param.orderLat}),POINT(dev.longitude,dev.latitude))*111195,0),100000000), dev.device_status, dev.device_code, ch.channel_code


        ORDER BY dev.device_status, dev.device_code, ch.channel_code

SELECT DISTINCT dev.device_code
FROM vm_device_info_t dev
LEFT JOIN vm_order_devices t1 ON dev.device_code = t1.device_code
LEFT JOIN vm_channel_info_t ch ON ch.device_code = dev.device_code

    LEFT JOIN vm_organ_device_rel_t rel on rel.device_code=dev.device_code AND rel.delete_flag='0' AND rel.device_type = 4

WHERE t1.delete_flag = '0' AND dev.delete_flag = '0' AND ch.delete_flag = '0' AND t1.ord_status in (0,1,2)
AND dev.device_code != '' AND dev.device_code IS NOT NULL
AND ch.channel_code != '' AND ch.channel_code IS NOT NULL

    AND rel.dept_id LIKE CONCAT(#{param.orgId},'%')


    AND dev.model_code = #{param.modelCode}


    AND (dev.device_name like CONCAT(CONCAT('%', #{param.devChanName}),'%') OR dev.device_code like CONCAT(CONCAT('%', #{param.devChanName}),'%')
    OR ch.channel_code like CONCAT(CONCAT('%', #{param.devChanName}),'%') OR ch.channel_name like CONCAT(CONCAT('%', #{param.devChanName}),'%'))


    AND dev.model_code IN

        #{modelCodeItem}



    AND  dev.province_id = #{param.deviceArea}


    AND  dev.city_id = #{param.deviceArea}


    AND  dev.county_id = #{param.deviceArea}


    AND  dev.town_code = #{param.deviceArea}


    AND (dev.device_name like CONCAT('%', #{param.keyWords}, '%') or dev.device_code like CONCAT('%', #{param.keyWords}, '%'))


${param.dataScope}


        ORDER BY IFNULL(ROUND(ST_DISTANCE(POINT(#{param.orderLong},#{param.orderLat}),POINT(dev.longitude,dev.latitude))*111195,0),100000000), dev.device_status, dev.device_code, ch.channel_code


        ORDER BY dev.device_status, dev.device_code, ch.channel_code

SELECT /*+ set(enable_nestloop off)*/ od.order_code, od.tenant_id, dev.device_code, dev.model_code, ( CASE WHEN length( IFNULL( tdr.device_name, '' )) = 0 THEN dev.device_name ELSE tdr.device_name END ) AS dev_name, dev.site_code, dev.site_name, dev.device_status AS STATUS, dev.latitude, dev.longitude, dev.location, dev.height, dev.category_code, device_model_code,
cha.channel_code,cha.channel_name,
( SELECT DICT_LABEL FROM sys_dict_data WHERE DICT_TYPE = '103' AND DICT_VALUE = dev.model_code LIMIT 1 ) modelName, dev.visual_radius, dev.alarm_location, ( CASE WHEN length( IFNULL( tdr.device_name, '' )) = 0 THEN dev.device_name ELSE tdr.device_name END ) AS deviceName, dev.device_status, dev.adm_code, od.industry_code, dev.model_code AS modelId, dev.collect_type, dev.collect_method, dev.alarm_location, pro.area_name AS province_name, pro.area_code AS province_code, city.area_name AS city_name, city.area_code AS city_code, county.area_name AS county_name, county.area_code AS county_code, town.area_code AS street_code, town.area_name AS street_name, ( CASE WHEN dev.device_status = '0' THEN '在线' WHEN dev.device_status = '1' THEN '离线' WHEN dev.device_status = '2' THEN '从未连接' END ) deviceStatusName, ( CASE WHEN od.ord_status IN ( '0', '1', '2' ) THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END ) orderStatusName, od.ord_status AS orderStatus FROM vm_device_info_t dev LEFT JOIN vm_order_devices od ON od.delete_flag = '0' AND od.device_code = dev.device_code LEFT JOIN vm_tenant_device_channel_rel_t tdr ON tdr.device_code = dev.device_code AND tdr.tenant_id = od.tenant_id AND tdr.industry_code = od.industry_code LEFT JOIN sys_area pro ON pro.area_code = dev.province_id LEFT JOIN sys_area city ON city.area_code = dev.city_id LEFT JOIN sys_area county ON county.area_code = dev.county_id LEFT JOIN sys_area town ON town.area_code = dev.town_code
left join vm_order_package vop on vop.order_code = od.order_code and vop.delete_flag = '0'
left join vm_channel_info_t cha on dev.device_code = cha.device_code
WHERE od.device_code = #{deviceCode}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{orderStatus}
and cha.channel_code = #{channelCode}
${dataScope} limit 1

SELECT DISTINCT chan.channel_code, chan.device_code, (case when length(IFNULL(tcr.channel_name, '')) = 0 then chan.channel_name else tcr.channel_name end) as channel_name, chan.channel_status as status,chan.stream_type,chan.max_guard, chan.max_preset,chan.max_patrol,chan.facade,chan.channel_type, chan.visual_range,chan.horiz_range,chan.verti_range,chan.creator, chan.creator_date,chan.modifier,chan.modifier_date,chan.delete_flag, chan.channel_status as channelStatus, chan.device_code as parentDeviceCode, od.tenant_id FROM vm_channel_info_t chan LEFT JOIN vm_order_devices od ON od.device_code = chan.device_code LEFT JOIN vm_tenant_device_channel_rel_t tcr on tcr.device_code = od.device_code AND tcr.tenant_id = od.tenant_id AND tcr.channel_code = chan.channel_code AND tcr.industry_code = od.industry_code
left join vm_order_package vop on vop.order_code = od.order_code and vop.delete_flag = '0'
WHERE od.delete_flag = '0' AND chan.delete_flag = '0'
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
AND od.device_code= #{param.deviceCode}
and od.tenant_id = #{param.tenantId}
and od.industry_code = #{param.industryCode}
${param.dataScope} ORDER BY chan.channel_code

SELECT DISTINCT chan.channel_code, chan.device_code, (case when length(IFNULL(tcr.channel_name, '')) = 0 then chan.channel_name else tcr.channel_name end) as channel_name, chan.channel_status as status,chan.stream_type,chan.max_guard, chan.max_preset,chan.max_patrol,chan.facade,chan.channel_type, chan.visual_range,chan.horiz_range,chan.verti_range,chan.creator, chan.creator_date,chan.modifier,chan.modifier_date,chan.delete_flag FROM vm_channel_info_t chan LEFT JOIN vm_order_devices aa ON aa.device_code = chan.device_code LEFT JOIN vm_tenant_device_channel_rel_t tcr on tcr.device_code = aa.device_code AND tcr.tenant_id = aa.tenant_id AND tcr.channel_code = chan.channel_code AND tcr.industry_code = aa.industry_code LEFT JOIN vm_device_info_t dev ON chan.device_code = dev.device_code WHERE aa.delete_flag = '0' AND chan.delete_flag = '0' AND aa.ord_status IN ( 0, 1, 2 ) AND dev.delete_flag = '0' AND dev.device_code != '' AND dev.device_code IS NOT NULL AND chan.channel_code != '' AND chan.channel_code IS NOT NULL AND chan.channel_status = 0 ${param.dataScope}
AND aa.device_code= #{param.deviceCode}
and aa.tenant_id = #{param.tenantId}
and aa.industry_code = #{param.industryCode}
ORDER BY IFNULL(ROUND(ST_DISTANCE(POINT(#{param.orderLong},#{param.orderLat}),POINT(dev.longitude,dev.latitude))*111195,0),100000000), dev.device_status, dev.device_code, chan.channel_code
ORDER BY dev.device_status, dev.device_code, chan.channel_code
LIMIT 8

SELECT DISTINCT d.device_code,ifnull(b.DEVICE_NAME,a.device_name) as dev_name
FROM vm_order_devices d LEFT JOIN vm_device_info_t a on d.device_code=a.device_code
left join vm_tenant_device_channel_rel_t b on b.device_code=d.device_code AND b.industry_code=d.industry_code

    and b.TENANT_ID=#{param.tenantId}

WHERE d.ord_status in (0, 1, 2)
${param.dataScope}

    and (a.device_name like concat('%',#{param.devName,jdbcType=VARCHAR},'%') or b.DEVICE_NAME like concat('%',#{param.devName,jdbcType=VARCHAR},'%'))


    and a.province_id=#{param.provinceId}


    and a.city_id=#{param.cityId}


    and a.county_id=#{param.countyId}

SELECT DISTINCT od.device_code AS deviceCode, ( CASE WHEN length( IFNULL( ten.device_name, '' )) = 0 THEN m.device_name ELSE ten.device_name END ) device_name FROM vm_order_sensor_devices od LEFT JOIN vm_iot_device_t m ON m.device_code = od.device_code AND m.category_code = 2 LEFT JOIN vm_tenant_iot_device_rel_t ten ON ten.device_code = od.device_code AND ten.tenant_id = od.tenant_id AND ten.delete_flag = '0' AND ten.industry_code = od.industry_code WHERE od.delete_flag = '0' AND od.ord_status in (0, 1, 2) AND m.delete_flag = '0' AND od.category_code = 2 AND od.tenant_id = #{param.tenantId} ${param.dataScope}
and (ten.device_name like concat('%',#{param.deviceName,jdbcType=VARCHAR},'%') or m.device_name like concat('%',#{param.deviceName,jdbcType=VARCHAR},'%'))
AND (od.device_code LIKE CONCAT('%',#{param.codeOrName},'%') OR (ten.device_name LIKE CONCAT('%',#{param.codeOrName},'%')) OR (m.device_name LIKE CONCAT('%',#{param.codeOrName},'%')))

SELECT t1.record_plan_id, t1.device_code, t1.channel_code, ( case when length(IFNULL(tdr.device_name, '')) = 0 then t4.device_name else tdr.device_name end ) devName, ( case when length(IFNULL(tdr.channel_name, '')) = 0 then t3.channel_name else tdr.channel_name end ) channel_name FROM vm_channel_video_plan_t t1 LEFT JOIN vm_channel_info_t t3 ON t1.channel_code = t3.channel_code LEFT JOIN vm_device_info_t t4 ON t1.device_code = t4.device_code inner JOIN sys_tenant_info t5 ON t1.tenant_id = t5.tenant_id LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = t1.device_code AND tdr.tenant_id = t1.tenant_id AND tdr.channel_code = t1.channel_code AND tdr.industry_code = t1.industry_code and tdr.delete_flag='0' WHERE t1.delete_flag = '0' AND(
(t1.device_code = #{labelIdItem.deviceCode} and t1.channel_code = #{labelIdItem.channelCode})
)
and t1.tenant_id = #{tenantId}
and t1.industry_code = #{industryCode}

SELECT DISTINCT p.storage_time, d.device_code, t3.channel_code channelCodesStr, ( case when length(IFNULL(tdr.device_name, '')) = 0 then t4.device_name else tdr.device_name end ) devName, ( case when length(IFNULL(tdr.channel_name, '')) = 0 then t3.channel_name else tdr.channel_name end ) channel_name FROM vm_order_package p INNER JOIN vm_order_devices d ON p.package_code = d.package_code AND p.order_code = d.order_code AND p.tenant_id = d.tenant_id LEFT JOIN vm_channel_info_t t3 ON d.device_code = t3.device_code LEFT JOIN vm_device_info_t t4 ON d.device_code = t4.device_code LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = d.device_code AND tdr.tenant_id = d.tenant_id AND tdr.channel_code = t3.channel_code AND tdr.industry_code = d.industry_code and tdr.delete_flag='0' WHERE p.delete_flag = '0' AND d.delete_flag = '0' AND d.ord_status in (0,1,2)
AND d.tenant_id = #{customerCode}
and d.industry_code = #{industryCode}
AND d.device_code = #{deviceCode}
AND t3.channel_code = #{channelCodesStr}
AND #{storageDay} > CONVERT(p.storage_time,SIGNED)
AND(
(d.device_code = #{item.deviceCode} and t3.channel_code = #{item.channelCode} )
)

select t.order_code
from vm_order_devices t
         left join vm_channel_info_t t1 on t1.device_code = t.device_code
where t1.channel_code = #{channelCode}
  AND t.tenant_id = #{tenantId}
  AND t.delete_flag = '0'  AND t.ord_status in (0, 1, 2)

select DISTINCT t2.longitude, t2.latitude, t2.height, t2.site_code from vm_order_devices t1 INNER join vm_device_info_t t2 on t1.device_code = t2.device_code INNER join vm_channel_info_t t3 on t2.device_code = t3.device_code where t1.delete_flag = '0' and t2.delete_flag = '0' and t3.delete_flag = '0' and t1.ord_status in (0, 1, 2)
and t1.device_code != #{param.deviceCode}
AND (t2.site_code like CONCAT(CONCAT('%', #{param.deviceName}),'%')OR t2.device_name like CONCAT(CONCAT('%', #{param.deviceName}),'%'))
AND #{param.distance} >= ST_DISTANCE(POINT(#{param.longitude},#{param.latitude}),POINT(t2.longitude,t2.latitude))*111195
${param.dataScope}

SELECT DISTINCT dataTable.label_id AS labelId, dataTable.label_name AS labelName, d.`device_code` AS deviceCode, IFNULL(dr.device_name, d.device_name) AS deviceName, IFNULL(dr.channel_name, c.channel_name) AS channelName, c.`channel_status` AS status, c.`channel_code` AS channelCode, d.`longitude`, d.`latitude`, 'false' AS checked, 1 AS num, 1 as labelLevel, 2 as devLevel, 3 as chanLevel, IF(c.channel_status = '0', 1, 0) AS onlineNum, case when IFNULL(dc.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, dc.user_device_coll_id, c.facade, d.category_code FROM (SELECT l.`label_id`, l.`label_name`, l.`tenant_id`, rel.`device_code`,l.industry_code FROM vm_device_labels_rel rel INNER JOIN vm_tenant_label_config l USING (label_id) WHERE l.delete_flag = 0) dataTable LEFT JOIN vm_device_info_t d ON dataTable.device_code = d.`device_code` LEFT JOIN vm_channel_info_t c ON dataTable.device_code = c.`device_code` left join vm_order_devices vod on vod.device_code = d.device_code and vod.delete_flag = '0' and vod.tenant_id = dataTable.tenant_id LEFT JOIN vm_tenant_device_channel_rel_t dr on dr.device_code = dataTable.device_code AND dr.tenant_id = dataTable.tenant_id AND dr.channel_code = c.channel_code AND dr.industry_code = vod.industry_code AND dr.delete_flag = '0' LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = c.channel_code AND dc.coll_obj_type = '6' and dc.user_id = #{userId}
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = d.device_code and c.channel_code = vcdit.channel_code and vcdit.delete_flag = '0' and vod.tenant_id = vcdit.tenant_id AND vod.industry_code = vcdit.industry_code
WHERE d.`delete_flag` = '0' and vod.ord_status in (0,1,2) ${dataScope}
and dc.user_device_coll_id IS NOT NULL
AND d.device_code IN
#{item}
and d.category_code in
#{item}
ORDER BY dataTable.label_id, d.device_code, c.channel_code

SELECT DISTINCT dataTable.id AS labelTypeId, dataTable.label_type_name AS labelTypeName, dataTable.label_id AS labelId, dataTable.label_name AS labelName, d.device_code AS deviceCode, IFNULL(dr.device_name, d.device_name) AS deviceName, IFNULL(dr.channel_name, c.channel_name) AS channelName, c.channel_status AS status, c.channel_code AS channelCode, d.longitude, d.latitude, 'false' AS checked, 1 AS num, 1 as labelTypeLevel, 2 as labelLevel, 3 as devLevel, 4 as chanLevel, IF(c.channel_status = '0', 1, 0) AS onlineNum, case when IFNULL(dc.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, dc.user_device_coll_id, c.facade, d.category_code, d.site_code,d.device_status,d.image_url FROM (SELECT l.label_id, l.label_name, l.tenant_id, rel.device_code,l.industry_code,lt.id,lt.label_type_name FROM vm_device_labels_rel rel LEFT JOIN vm_tenant_label_config l ON rel.label_id = l.label_id AND rel.tenant_id = l.tenant_id LEFT JOIN vm_tenant_label_type_config lt ON lt.id = l.label_type_id AND lt.tenant_id = l.tenant_id AND lt.industry_code = l.industry_code WHERE l.delete_flag = 0 AND lt.delete_flag = 0) dataTable LEFT JOIN vm_device_info_t d ON dataTable.device_code = d.device_code LEFT JOIN vm_channel_info_t c ON dataTable.device_code = c.device_code left join vm_order_devices vod on vod.device_code = d.device_code and vod.delete_flag = '0' and vod.tenant_id = dataTable.tenant_id and vod.industry_code = dataTable.industry_code LEFT JOIN vm_tenant_device_channel_rel_t dr on dr.device_code = dataTable.device_code AND dr.tenant_id = dataTable.tenant_id AND dr.channel_code = c.channel_code AND dr.industry_code = dataTable.industry_code AND dr.delete_flag = '0' LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = c.channel_code AND dc.coll_obj_type = '6' and dc.user_id = #{userId}
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = d.device_code and c.channel_code = vcdit.channel_code and vcdit.delete_flag = '0' and vod.tenant_id = vcdit.tenant_id AND vod.industry_code = vcdit.industry_code
join vm_water_level_info_t water on water.device_code = d.device_code and water.delete_flag = '0' and vod.tenant_id = water.tenant_id AND vod.industry_code = water.industry_code
WHERE d.delete_flag = '0' AND c.delete_flag = '0' AND vod.ord_status in (0,1,2) ${dataScope}
and dc.user_device_coll_id IS NOT NULL
and d.category_code in
#{item}
AND d.device_code IN
#{item}
and c.channel_status in
#{item}
ORDER BY CASE WHEN dataTable.label_type_name REGEXP '^[a-zA-Z]' THEN 1 WHEN dataTable.label_type_name REGEXP '^[0-9]' THEN 2 ELSE 3 END, CONVERT(dataTable.label_type_name USING gbk), CASE WHEN dataTable.label_name REGEXP '^[a-zA-Z]' THEN 1 WHEN dataTable.label_name REGEXP '^[0-9]' THEN 2 ELSE 3 END, CONVERT(dataTable.label_name USING gbk), d.device_code, C.channel_code

SELECT DISTINCT od.device_code, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, town.area_code as street_code, town.area_name as street_name, m.device_status, m.longitude, m.latitude, m.location, m.model_code, od.tenant_id, pro.area_name as province_name, pro.area_code as province_code, city.area_name as city_name, city.area_code as city_code, county.area_name as county_name, county.area_code as county_code, m.adm_code, m.height, m.category_code, c.channel_code, c.channel_name, c.channel_status, c.visual_range, c.horiz_range, c.verti_range FROM vm_order_devices od LEFT JOIN vm_device_info_t m on m.device_code = od.device_code and m.delete_flag='0' LEFT JOIN vm_channel_info_t c on c.device_code = od.device_code and c.delete_flag='0' LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = od.device_code and ten.delete_flag='0' and ten.tenant_id = od.tenant_id and ten.industry_code = od.industry_code LEFT JOIN sys_area pro on pro.area_code = m.province_id LEFT JOIN sys_area city on city.area_code = m.city_id LEFT JOIN sys_area county on county.area_code = m.county_id LEFT JOIN sys_area town on town.area_code = m.town_code where od.delete_flag = '0' AND od.ord_status in (0, 1, 2)
and m.device_code = #{deviceCode}
and od.app_ver_code = #{appVerCode}
${dataScope} order by pro.area_code, city.area_code, county.area_code

select de.device_name, ord.device_name, lc.label_id, lc.label_name, ord.tenant_id, de.device_code, ord.device_code, de.device_name, ch.channel_code, ch.channel_name, ch.channel_status, de.longitude, de.latitude, de.site_code, de.device_status, case when exists (select * from vm_user_device_collection_t t where t.user_id = #{userId} AND t.coll_obj_type = '3' and lc.label_id=t.coll_obj_code) then '1' else '0' end labelIsCollection, case when exists (select * from vm_user_device_collection_t t where t.user_id = #{userId} AND t.coll_obj_type = '5' and ord.device_code=t.coll_obj_code) then '1' else '0' end deviceIsCollection, case when exists (select * from vm_user_device_collection_t t where t.user_id = #{userId} AND t.coll_obj_type = '6' and ch.channel_code=t.coll_obj_code) then '1' else '0' end channelIsCollection,
ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance,
'1' labelLevel, '2' deviceLevel, '3' channelLevel, de.category_code from vm_order_devices ord left join vm_device_info_t de on ord.device_code = de.device_code left join vm_channel_info_t ch on ch.device_code = ord.device_code left join vm_device_labels_rel lr on lr.tenant_id = ord.tenant_id and lr.device_code = ord.device_code left join vm_tenant_label_config lc on lc.label_id = lr.label_id and lc.tenant_id = ord.tenant_id
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = ord.device_code and ch.channel_code = vcdit.channel_code and vcdit.delete_flag = '0' and ord.tenant_id = vcdit.tenant_id
where ord.delete_flag = '0' and de.delete_flag = '0' and ch.delete_flag = '0' and lc.label_name is not null and ord.ord_status in (0, 1, 2) ${dataScope}
and ord.app_ver_code = #{appVerCode}
and ord.device_name like CONCAT(CONCAT('%', #{keyWords}),'%') or ch.channel_name like CONCAT(CONCAT('%', #{keyWords}),'%')
and de.category_code = #{categoryCode}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 <= #{radius}
and ( exists ( select coll_obj_code from vm_user_device_collection_t t where t.user_id = #{userId} and t.coll_obj_type = '3' and t.coll_obj_code=lr.label_id ) or exists ( select coll_obj_code from vm_user_device_collection_t t where t.user_id = #{userId} and t.coll_obj_type = '5' and t.coll_obj_code=ord.device_code ) or exists ( select coll_obj_code from vm_user_device_collection_t t where t.user_id = #{userId} and t.coll_obj_type = '6' and t.coll_obj_code=ch.channel_code ) )
and not exists ( select coll_obj_code from vm_user_device_collection_t t where t.user_id = #{userId} and t.coll_obj_type = '3' and t.coll_obj_code=lr.label_id ) and not exists ( select coll_obj_code from vm_user_device_collection_t t where t.user_id = #{userId} and t.coll_obj_type = '5' and t.coll_obj_code=ord.device_code ) and not exists ( select coll_obj_code from vm_user_device_collection_t t where t.user_id = #{userId} and t.coll_obj_type = '6' and t.coll_obj_code=ch.channel_code )
order by ord.device_code

SELECT DISTINCT d.device_code, d.device_name, d.device_status, d.height, d.longitude, d.latitude, d.location, d.province_id, d.city_id, d.county_id
