ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance,
c.channel_id, c.channel_code, c.channel_name, c.channel_status, c.stream_type, c.max_guard, c.max_preset, c.max_patrol, c.facade, c.channel_type, c.visual_range, c.horiz_range, c.verti_range, c.creator, c.creator_date, c.modifier, c.modifier_date, c.delete_flag, de.category_code, de.device_status, de.image_url from vm_order_devices ord left join vm_device_info_t de on ord.device_code = de.device_code left join vm_channel_info_t c on c.device_code = de.device_code
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = ord.device_code and c.channel_code = vcdit.channel_code and vcdit.delete_flag = '0' and ord.tenant_id = vcdit.tenant_id AND ord.industry_code = vcdit.industry_code
where ord.delete_flag = '0' and de.delete_flag = '0' and c.delete_flag = '0' and ord.ord_status in (0,1,2)
and de.category_code=#{categoryCode}
AND ord.device_code IN
#{item}
and ord.app_ver_code = #{appVerCode}
${dataScope}
and de.province_id = #{provinceId}
AND de.city_id = #{cityId}
AND de.county_id = #{countyId}
) AS subquery where 1 = 1
and #{distance} >= subquery.distance
and (subquery.device_name like CONCAT('%', #{keyWords}, '%') or subquery.device_code like CONCAT('%', #{keyWords}, '%'))
order by subquery.distance
