de.device_status = #{deviceStatus}
${dataScope}

SELECT dev.device_code, case when dc.user_device_coll_id is null then 0 else 1 end as isMonitor FROM vm_device_info_t dev LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = dev.device_code AND dc.coll_obj_type = '5' AND dc.user_id = #{userId} WHERE dev.delete_flag = '0'
AND dev.device_code in
#{id}

SELECT t1.dept_id,t1.dept_id AS code,t1.dept_name,t1.dept_name AS name,t1.dept_level AS level, t1.parent_id AS parentCode,'false' AS checked, 0 AS number, 0 AS onLineNumber FROM sys_dept t1 WHERE t1.del_flag = '0'
AND t1.dept_id in
#{item}
and t1.tenant_id = #{tenantId}

select d.device_code , d.device_name , d.device_status , d.height , d.longitude , d.latitude , d.site_code , d.monitor_angle , d.monitor_direction , d.device_sub_type , t.model_id , t.mfgr_code , t.device_model_code , t.device_type , t.pic_sensor_size , t.pic_sensor_length , t.pic_sensor_width , t.min_focus , t.focus_range , t.horiz_view_range , t.verti_view_range , t.horiz_range , t.verti_range , t.verti_down_neg , t.remark , CAST(d.visual_radius AS CHAR)/1000 as visual_range , dp.point_id , dp.hor_offset , dp.pitch_offset , dp.pan from vm_device_info_t d left join vm_device_model_t t on d.device_model_code = t.device_model_code and d.model_code = t.mfgr_code left join vm_device_ref_point_valid_t dp on d.device_code = dp.device_code and dp.point_flag = '1' where
d.device_code in
#{item}
d.device_code = #{deviceCode}
order by dp.pan

select DISTINCT de.longitude, de.latitude, de.height,
ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance,
de.device_code, ( case when length(IFNULL(ten.device_name, '')) = 0 then de.device_name else ten.device_name end ) device_name, ch.channel_code, ( case when length(IFNULL(ten.channel_name, '')) = 0 then ch.channel_name else ten.channel_name end ) channel_name from vm_order_devices ord left join vm_order_customer voc on ord.order_code = voc.order_code left join vm_device_info_t de on ord.device_code = de.device_code left join vm_channel_info_t ch on de.device_code = ch.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = ord.device_code AND ch.channel_code = ten.channel_code AND ten.tenant_id = ord.tenant_id AND ten.industry_code = ord.industry_code and ten.delete_flag='0' where ord.delete_flag = '0' and voc.delete_flag = '0' and de.delete_flag = '0' and ch.delete_flag = '0' and ch.channel_status = '0'
and ord.device_code != #{deviceCode}
and voc.ord_status in (0, 1, 2) ${dataScope}
order by distance asc limit 1

select label_id,label_name from vm_tenant_label_config where label_id in
(select label_id from vm_device_labels_rel where device_code = #{deviceCode}) and tenant_id = #{tenantId}

    and industry_code = #{industryCode}

select distinct device_code,device_name,ord_status,industry_code,app_ver_code
from vm_order_devices
where tenant_id = #{param.tenantId}
  and industry_code = #{param.industryCode}
  and ord_status in (0,1,2)

select distinct device_code,device_name,ord_status,industry_code,app_ver_code
from vm_order_sensor_devices
where tenant_id = #{param.tenantId}
  and industry_code = #{param.industryCode}
  and category_code = 1
  and ord_status in (0,1,2)

select distinct device_code,device_name,ord_status,industry_code,app_ver_code
from vm_order_sensor_devices
where tenant_id = #{param.tenantId}
  and industry_code = #{param.industryCode}
  and category_code = 2
  and ord_status in (0,1,2)

select distinct service_code,service_name,ord_status,industry_code,app_ver_code
from vm_order_services_rel
where tenant_id = #{param.tenantId}
  and industry_code = #{param.industryCode}
  and service_code = '9'
  and ord_status in (0,1,2)

SELECT ord.device_code deviceCode, de.device_name deviceName, de.device_status deviceStatus, de.location,
de.device_code, de.device_status status, ifnull(de.height, 0) as height, de.latitude, de.longitude,

    IFNULL(ROUND(ST_DISTANCE(POINT(#{dto.orderLong},#{dto.orderLat}),POINT(de.longitude,de.latitude))*111195,0),100000000) as rangeMeter,

de.site_code, de.model_code, dict.dict_label model_name
FROM vm_order_devices ord
INNER JOIN vm_device_info_t de USING ( device_code )
INNER JOIN vm_channel_info_t ch USING ( device_code )
LEFT JOIN sys_dict_data dict ON dict_type = 103 AND dict.dict_value = de.model_code
LEFT JOIN vm_organ_device_rel_t odr ON odr.tenant_id = ord.tenant_id
AND odr.device_code = ord.device_code AND odr.device_type = 4
LEFT JOIN vm_device_labels_rel lr ON lr.tenant_id = ord.tenant_id AND lr.device_code = ord.device_code
LEFT JOIN sys_dept sd ON sd.TENANT_ID = ord.tenant_id AND sd.DEPT_ID = odr.DEPT_ID
WHERE ord.tenant_id = #{dto.tenantId} AND ord.industry_code = #{dto.industryCode}
AND ord.delete_flag = '0' AND de.delete_flag = '0' AND ch.delete_flag = '0' AND ord.ord_status IN ( 0, 1, 2 )
AND (
EXISTS ( SELECT 1 FROM vm_user_device_collection_t t WHERE t.user_id = #{dto.userId} AND t.coll_obj_type = '5' AND t.coll_obj_code = ord.device_code )
OR EXISTS (SELECT 1 FROM vm_user_device_collection_t t where t.user_id = #{dto.userId} and t.coll_obj_type = '6' and t.coll_obj_code=ch.channel_code)
)

    AND (de.device_name like CONCAT('%', #{dto.keyWords}, '%') or ord.device_code like CONCAT('%', #{dto.keyWords}, '%'))


    AND  de.device_status = #{dto.deviceStatus}


    AND  de.model_code = #{dto.modelCode}


    and de.model_code  IN

        #{modelCodeItem}



    AND  de.province_id = #{dto.deviceArea}


    AND  de.city_id = #{dto.deviceArea}


    AND  de.county_id = #{dto.deviceArea}


    AND  de.town_code = #{dto.deviceArea}

GROUP BY ord.device_code


        ORDER BY rangeMeter, de.device_status, de.device_code


        ORDER BY de.device_status, de.device_code

SELECT DISTINCT chan.channel_code, chan.device_code, (case when length(IFNULL(tcr.channel_name, '')) = 0 then chan.channel_name else tcr.channel_name end) as channel_name, chan.channel_status as status ,case when IFNULL(dc.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
IFNULL(ROUND(ST_DISTANCE(POINT(#{param.orderLong},#{param.orderLat}),POINT(dev.longitude,dev.latitude))*111195,0),100000000) as rangeMeter,
dev.longitude,dev.latitude,dev.location,ifnull(dev.height, 0) as height,dev.model_code,dict.dict_label model_name FROM vm_channel_info_t chan LEFT JOIN vm_order_devices aa ON aa.device_code = chan.device_code LEFT JOIN vm_tenant_device_channel_rel_t tcr on tcr.device_code = aa.device_code AND tcr.tenant_id = aa.tenant_id AND tcr.channel_code = chan.channel_code AND tcr.industry_code = aa.industry_code LEFT JOIN vm_user_device_collection_t dc on dc.coll_obj_code = chan.channel_code AND dc.coll_obj_type = '6' and dc.user_id = #{param.userId} LEFT JOIN vm_device_info_t dev on chan.device_code = dev.device_code LEFT JOIN sys_dict_data dict on dict_type = '103' and dict.dict_value = dev.model_code WHERE aa.delete_flag = '0' AND chan.delete_flag = '0' AND aa.ord_status IN ( 0, 1, 2 ) and dev.device_code is not null and dev.device_code !=''
and dc.user_device_coll_id IS NOT NULL
AND chan.channel_status = #{param.deviceStatus}
and dev.model_code IN
#{modelCodeItem}
AND dev.province_id = #{param.deviceArea}
AND dev.city_id = #{param.deviceArea}
AND dev.county_id = #{param.deviceArea}
AND dev.town_code = #{param.deviceArea}
AND (dev.device_name like CONCAT('%', #{param.keyWords}, '%') or dev.device_code like CONCAT('%', #{param.keyWords}, '%'))
${param.dataScope}
ORDER BY rangeMeter, chan.channel_status,chan.channel_code
ORDER BY chan.channel_status, chan.channel_code

