SELECT DISTINCT ord.tenant_id,ord.industry_code,ord.device_code,us.USER_ID,us.USER_NAME,us.NICK_NAME, us.STATUS,oac.priority as cameraPriority ,oac.operate_period as cameraOperatePeriodList,oac.camera_status,oac.preset_priority,oac.preset_operate_period as presetOperatePeriodList ,oac.preset_status,oac.patrol_priority, oac.patrol_operate_period as patrolOperatePeriodList,oac.patrol_status,oac.guard_priority,oac.guard_operate_period as guardOperatePeriodList,oac.guard_status,d.DEPT_NAME as deptName,d.dept_id as deptId,us.CREATE_TIME as createTime FROM sys_user us JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT us_inner.USER_ID, SUBSTRING_INDEX(SUBSTRING_INDEX(us_inner.DEPT_ID, ',', n), ',', -1) AS dept_id FROM sys_user us_inner JOIN cte ON cte.n <= ( LENGTH(us_inner.DEPT_ID) - LENGTH(REPLACE(us_inner.DEPT_ID, ',', '')) + 1 ) WHERE us_inner.DEL_FLAG = '0' ) ud ON us.USER_ID = ud.USER_ID LEFT JOIN sys_dept d ON ud.dept_id = d.DEPT_ID AND d.del_flag = '0' LEFT JOIN vm_order_devices ord ON ord.tenant_id = us.tenant_id AND ord.industry_code = d.industry_code LEFT JOIN vm_device_operate_auth_config oac ON oac.industry_code = d.industry_code AND oac.tenant_id = us.tenant_id AND oac.config_type = '2' AND oac.device_code = ord.device_code AND oac.user_id = us.USER_ID AND oac.delete_flag = 0 WHERE us.DEL_FLAG = '0' AND us.USER_TYPE = '2' AND ord.ord_status IN (0,1,2) AND ord.device_code = #{deviceCode} ${dataScope}
AND us.USER_NAME LIKE concat('%',#{userName},'%')
AND us.NICK_NAME LIKE concat('%',#{nickName},'%')
AND us.STATUS = #{status}
AND d.dept_id = #{deptId}
and us.USER_ID in
#{id}
ORDER BY us.CREATE_TIME DESC

