ty} = '3' and patrol_priority in ('7','4','1') then '1' else patrol_priority end, guard_priority = case when #{guardPriority} = '9' and guard_priority in ('9','6','3') then '9' when #{guardPriority} = '9' and guard_priority in ('8','5','2') then '8' when #{guardPriority} = '9' and guard_priority in ('7','4','1') then '7' when #{guardPriority} = '6' and guard_priority in ('9','6','3') then '6' when #{guardPriority} = '6' and guard_priority in ('8','5','2') then '5' when #{guardPriority} = '6' and guard_priority in ('7','4','1') then '4' when #{guardPriority} = '3' and guard_priority in ('9','6','3') then '3' when #{guardPriority} = '3' and guard_priority in ('8','5','2') then '2' when #{guardPriority} = '3' and guard_priority in ('7','4','1') then '1' else guard_priority end, modifier = #{creator}, update_time = NOW() where delete_flag = 0
