ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance,
de.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then de.device_name else ten.device_name end ) device_name, ch.channel_code, ( case when length(IFNULL(ten.channel_name, '')) = 0 then ch.channel_name else ten.channel_name end ) channel_name from vm_order_devices ord left join vm_order_customer voc on ord.order_code = voc.order_code left join vm_device_info_t de on ord.device_code = de.device_code left join vm_channel_info_t ch on de.device_code = ch.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = ord.device_code AND ch.channel_code = ten.channel_code AND ten.tenant_id = ord.tenant_id AND ten.industry_code = ord.industry_code and ten.delete_flag='0' LEFT JOIN sys_area pro on pro.area_code = de.province_id LEFT JOIN sys_area city on city.area_code = de.city_id LEFT JOIN sys_area county on county.area_code = de.county_id LEFT JOIN sys_area town on town.area_code = de.town_code where ord.delete_flag = '0' and voc.delete_flag = '0' and de.delete_flag = '0' and ch.delete_flag = '0' and ch.channel_status = '0'
