t.device_code, t.device_name, t.longitude, t.latitude, t.distance, c.channel_id, c.channel_code, c.channel_name from ( select de.device_code, de.device_name, de.longitude,de.latitude, ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance from vm_order_devices ord left join vm_device_info_t de on ord.device_code = de.device_code where ord.delete_flag = '0' and de.delete_flag = '0' and ord.ord_status in (0, 1, 2) and de.device_status = 0 and ord.tenant_id = #{tenantId} and ord.industry_code = #{industryCode}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 <= #{distance}
) t left join vm_channel_info_t c on c.device_code = t.device_code and c.delete_flag = '0' and c.channel_status = 0 order by distance asc

