SELECT m1.province_id, m1.city_id, m1.county_id, m1.town_code, ch.channel_status, count( 1 ) AS channelStatusCount FROM ( SELECT DISTINCT coll_obj_code FROM vm_user_device_collection_t WHERE coll_obj_type = '6' AND user_id = #{param.userId}) dc LEFT JOIN vm_channel_info_t ch ON dc.coll_obj_code = ch.channel_code LEFT JOIN ( SELECT DISTINCT de.province_id, de.city_id, de.county_id, de.device_code, de.delete_flag, ( IF ( regexp_like ( de.town_code, '[^0-9]' ), NULL, de.town_code )) town_code, de.category_code FROM vm_device_info_t de ) m1 ON ch.device_code = m1.device_code LEFT JOIN vm_order_devices m ON m1.device_code = m.device_code WHERE m.ord_status IN ( 0, 1, 2 ) AND m.delete_flag = '0' AND m1.delete_flag = '0' AND ch.delete_flag = '0' AND m1.province_id != '' AND m1.province_id IS NOT NULL AND m1.city_id != '' AND m1.city_id IS NOT NULL AND m1.county_id != '' AND m1.county_id IS NOT NULL AND regexp_like ( m1.province_id, '[0-9]' ) AND regexp_like ( m1.city_id, '[0-9]' ) AND regexp_like ( m1.county_id, '[0-9]')
AND m1.category_code in
#{item}
and ch.channel_status in
#{item}
${param.dataScope} GROUP BY m1.province_id, m1.city_id, m1.county_id, m1.town_code, ch.channel_status ORDER BY m1.province_id, m1.city_id, m1.county_id, m1.town_code

SELECT m.province_id, m.city_id, m.county_id, m.town_code, ch.channel_status, count( 1 ) AS channelStatusCount FROM ( SELECT DISTINCT de.province_id, de.city_id, de.county_id, de.device_code, ord.tenant_id, ord.industry_code, ord.accept_node, ( IF ( regexp_like ( de.town_code, '[^0-9]' ), NULL, de.town_code )) town_code FROM vm_order_devices ord LEFT JOIN vm_device_info_t de ON de.device_code = ord.device_code AND de.delete_flag = '0' WHERE ord.ord_status IN ( 0, 1, 2 ) AND ord.delete_flag = '0' AND de.province_id != '' AND de.province_id IS NOT NULL AND de.city_id != '' AND de.city_id IS NOT NULL AND de.county_id != '' AND de.county_id IS NOT NULL AND regexp_like ( de.province_id, '[0-9]' ) AND regexp_like ( de.city_id, '[0-9]' ) AND regexp_like ( de.county_id, '[0-9]' )
AND de.category_code in
#{item}
) m LEFT JOIN vm_channel_info_t ch ON ch.device_code = m.device_code WHERE ch.delete_flag = '0'
and ch.channel_status in
#{item}
