SELECT m.province_id, m.city_id, m.county_id, m.town_code, count(DISTINCT m.device_code) AS videoNum FROM ( SELECT DISTINCT de.province_id, de.city_id, de.county_id, de.device_code, ord.tenant_id, ord.industry_code, ord.accept_node, ( IF ( regexp_like ( de.town_code, '[^0-9]' ), NULL, de.town_code )) town_code FROM vm_order_devices ord LEFT JOIN vm_device_info_t de ON de.device_code = ord.device_code AND de.delete_flag = '0' WHERE ord.ord_status IN ( 0, 1, 2 ) AND ord.delete_flag = '0' AND de.province_id != '' AND de.province_id IS NOT NULL AND de.city_id != '' AND de.city_id IS NOT NULL AND de.county_id != '' AND de.county_id IS NOT NULL AND regexp_like ( de.province_id, '[0-9]' ) AND regexp_like ( de.city_id, '[0-9]' ) AND regexp_like ( de.county_id, '[0-9]' )
AND de.category_code in
#{item}
) m LEFT JOIN vm_channel_info_t ch ON ch.device_code = m.device_code WHERE ch.delete_flag = '0'
and ch.channel_status in
#{item}
${param.dataScope} GROUP BY m.province_id, m.city_id, m.county_id, m.town_code ORDER BY m.province_id, m.city_id, m.county_id, m.town_code

select distinct t.tenant_id, t.device_code, t.industry_code, t.accept_node from vm_order_devices t where t.device_code in
#{deviceCode}
AND t.delete_flag = '0' AND t.ord_status in (0, 1, 2)

select distinct t.tenant_id, t.device_code, t.industry_code, t.accept_node from vm_order_sensor_devices t where t.device_code in
#{deviceCode}
AND t.delete_flag = '0' AND t.ord_status in (0, 1, 2)

SELECT DISTINCT gg.dept_id AS code, gg.dept_name AS name, gg.dept_level AS level, gg.parent_id AS parentCode, SUM(IF( cc.channel_status = '0', 1, 0 )) AS onlineNum, count( distinct dd.device_code) AS num FROM sys_dept gg LEFT JOIN vm_organ_device_rel_t dd ON gg.dept_id = dd.dept_id AND gg.industry_code = dd.industry_code AND dd.device_type = 4 LEFT JOIN vm_device_info_t m on dd.device_code = m.device_code LEFT JOIN vm_order_devices vod ON vod.tenant_id = gg.tenant_id AND vod.industry_code = dd.industry_code AND vod.device_code = dd.device_code LEFT JOIN vm_channel_info_t cc ON dd.device_code = cc.device_code WHERE gg.del_flag = '0' AND m.delete_flag = '0' AND dd.delete_flag = '0' AND cc.delete_flag = '0' AND dd.device_code IS NOT NULL AND dd.device_code != '' AND vod.delete_flag = '0' AND vod.ord_status IN ( 0, 1, 2 )
AND m.category_code in
#{item}
and cc.channel_status in
#{item}
${param.dataScope} GROUP BY gg.dept_id, gg.dept_name, gg.dept_level, gg.parent_id ORDER BY gg.dept_id

SELECT DISTINCT gg.dept_id AS code, gg.dept_name AS name, gg.dept_level AS level, gg.parent_id AS parentCode, SUM(IF( ch.channel_status = '0', 1, 0 )) AS onlineNum, count( DISTINCT dd.device_code) AS num FROM ( SELECT DISTINCT coll_obj_code FROM vm_user_device_collection_t WHERE coll_obj_type = '6' AND user_id = #{param.userId} ) dc LEFT JOIN vm_channel_info_t ch ON dc.coll_obj_code = ch.channel_code LEFT JOIN vm_organ_device_rel_t dd ON ch.device_code = dd.device_code LEFT JOIN vm_device_info_t m on dd.device_code = m.device_code LEFT JOIN sys_dept gg ON gg.dept_id = dd.dept_id AND gg.industry_code = dd.industry_code AND dd.device_type = 4 LEFT JOIN vm_order_devices vod ON dd.device_code = vod.device_code AND dd.tenant_id = vod.tenant_id AND dd.industry_code = vod.industry_code WHERE vod.ord_status IN ( 0, 1, 2 ) AND m.delete_flag = '0' AND vod.delete_flag = '0' AND dd.delete_flag = '0' AND ch.delete_flag = '0' AND gg.del_flag = '0' AND dd.device_code IS NOT NULL AND dd.device_code != ''
AND m.category_code in
#{item}
and ch.channel_status in
#{item}
${param.dataScope} GROUP BY gg.dept_id, gg.dept_name, gg.dept_level, gg.parent_id ORDER BY gg.dept_id

select * from ( SELECT DISTINCT m.device_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) device_name, CAST(LENGTH(SUBSTRING_INDEX(dd.dept_id, '-', -1)) / 2 AS UNSIGNED) + 1 AS devLevel, dd.dept_id parentCode, dd.dept_id parentUniCode, CONCAT( dd.dept_id, '_', m.device_code ) devUni, m.longitude, m.latitude, m.site_code, m.device_status, CASE WHEN IFNULL(dc.user_device_coll_id, 0) = 0 THEN '0' ELSE '1' END isMonitor, CASE WHEN IFNULL(dc.user_device_coll_id, 0) = 0 THEN 0 ELSE 1 END isMonitorNum, m.category_code, m.image_url, ch.channel_code, (case when length(IFNULL(dr.channel_name, '')) = 0 then ch.channel_name else dr.channel_name end ) channel_name, ch.channel_status, CAST(LENGTH(SUBSTRING_INDEX(dd.dept_id, '-', -1)) / 2 AS UNSIGNED) + 2 AS chanLevel, CONCAT( dd.dept_id, '_', m.device_code, '_', ch.channel_code ) chanUni, ch.facade FROM vm_device_info_t m LEFT JOIN vm_organ_device_rel_t dd ON m.device_code = dd.device_code LEFT JOIN vm_channel_info_t ch ON ch.device_code = m.device_code LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = ch.channel_code AND dc.coll_obj_type = '6' AND dc.user_id = #{param.userId} LEFT JOIN vm_order_devices ord ON ord.device_code = m.device_code LEFT JOIN vm_tenant_device_channel_rel_t dr on dr.device_code = ord.device_code and dr.delete_flag = '0' AND dr.tenant_id = ord.tenant_id and dr.industry_code = ord.industry_code AND dr.channel_code = ch.channel_code WHERE ord.ord_status IN ( 0, 1, 2 ) AND ord.delete_flag = '0' AND m.delete_flag = '0' AND ch.delete_flag = '0' ${param.dataScope}
and dc.user_device_coll_id IS NOT NULL
AND dd.DEPT_ID LIKE CONCAT(#{param.code}, '%')
AND dd.DEPT_ID = #{param.code}
AND ch.channel_status = #{param.channelStatus}
AND ch.channel_code = #{param.channelCode}
and ch.channel_code in
#{item}
and m.category_code in
#{item}
and ch.channel_status in
#{item}
ORDER BY dd.dept_id, m.device_code, ch.channel_code
LIMIT #{param.limitNum}
) a
WHERE a.device_name LIKE concat('%',#{param.deviceName},'%') OR a.channel_name LIKE concat('%',#{param.deviceName},'%')

SELECT DISTINCT m.site_code, m.province_id, m.city_id, m.county_id, (IF(regexp_like ( m.town_code, '[^0-9]' ), NULL, m.town_code)) townCode, m.device_status, m.category_code, m.image_url, m.device_code, m.device_name, '5' AS devLevel, IF(length(IFNULL((IF(regexp_like ( m.town_code, '[^0-9]' ), NULL, m.town_code)) , '')) = 0, m.county_id, m.town_code) AS parentCode, CONCAT(m.province_id,'_',m.city_id,'_',m.county_id,CASE WHEN IFNULL((IF(regexp_like ( m.town_code, '[^0-9]' ), NULL, m.town_code)), 0) = 0 THEN '_' ELSE CONCAT('_',m.town_code,'_') END, m.device_code) devUni, CONCAT(m.province_id,'_',m.city_id,'_',m.county_id,CASE WHEN IFNULL((IF(regexp_like ( m.town_code, '[^0-9]' ), NULL, m.town_code)), 0) = 0 THEN '' ELSE CONCAT('_',m.town_code) END) parentUniCode FROM vm_device_info_t m LEFT JOIN vm_channel_info_t ch ON ch.device_code = m.device_code LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = ch.channel_code AND dc.coll_obj_type = '6' AND dc.user_id = #{param.userId} LEFT JOIN vm_order_devices ord ON ord.device_code = m.device_code WHERE ord.ord_status IN ( 0, 1, 2 ) AND ord.delete_flag = '0' AND m.delete_flag = '0' AND ch.delete_flag = '0' ${param.dataScope}
and dc.user_device_coll_id IS NOT NULL
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId} AND m.town_code = #{param.townCode}
AND m.county_id = #{param.countyId} AND m.town_code IS NULL
AND ch.channel_status = #{param.channelStatus}
AND ch.channel_code = #{param.channelCode}
and ch.channel_code in
#{item}
and m.category_code in
#{item}
and ch.channel_status in
#{item}
ORDER BY m.device_code

SELECT DISTINCT m.device_code, m.device_name, m.site_code, m.longitude, m.latitude, m.province_id, m.city_id, m.county_id, (IF(regexp_like ( m.town_code, '[^0-9]' ), NULL, m.town_code)) townCode, ch.channel_code, ch.channel_name, ch.channel_status, '6' AS chanLevel, ch.facade, CASE WHEN IFNULL(dc.user_device_coll_id, 0) = 0 THEN '0' ELSE '1' END isMonitor, CASE WHEN IFNULL(dc.user_device_coll_id, 0) = 0 THEN 0 ELSE 1 END isMonitorNum, CONCAT(m.province_id,'_',m.city_id,'_',m.county_id, CASE WHEN IFNULL((IF(regexp_like ( m.town_code, '[^0-9]' ), NULL, m.town_code)), 0) = 0 THEN '_' ELSE CONCAT('_',m.town_code,'_') END, m.device_code,'_',ch.channel_code) chanUni FROM vm_device_info_t m LEFT JOIN vm_channel_info_t ch ON ch.device_code = m.device_code LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = ch.channel_code AND dc.coll_obj_type = '6' AND dc.user_id = #{userId} WHERE m.delete_flag = '0' AND ch.delete_flag = '0' AND m.device_code IN
#{item}
ORDER BY m.device_code, ch.channel_code
